<?php
namespace SenderSuite;

/** Registry operations and preview analysis; no provider transport. */
final class Variables {
    private $db;private $records;
    public function __construct(Database $db,callable $clock=null){$this->db=$db;$this->records=new Records($db,$clock);}
    private function table($name){return Schema::identifier($this->db->schema()->table($name));}
    private static function standards(){return json_decode(file_get_contents(dirname(__DIR__).'/schema/standard-variables.json'),true,512,JSON_THROW_ON_ERROR);}
    private function rows(){return $this->db->select('contact_variables',array(),2147483647);}
    public static function humanize($key){$out=array();foreach(explode('_',$key) as $part){if($part!==''){$out[]=ucfirst(strtolower($part));}}return $out?implode(' ',$out):$key;}
    public static function input($body,$update=false){if(!is_object($body)){throw new ValidationFailure('Input should be a valid dictionary or object to extract fields from');}$out=$update?array():array('field_key'=>null,'label'=>null,'shortcode'=>null,'fallback_text'=>null,'description'=>null);$fields=$update?array('label','shortcode','fallback_text','description','is_active'):array('field_key','label','shortcode','fallback_text','description');foreach($fields as $field){if(!property_exists($body,$field)){if(!$update&&$field==='field_key'){throw new ValidationFailure('Field required',$field);}continue;}$v=$body->$field;if($field==='is_active'){$out[$field]=$v===null?null:DataRoutes::boolean($v,$field);continue;}if(($v===null&&$field==='field_key')||($v!==null&&!is_string($v))){throw new ValidationFailure('Input should be a valid string',$field);}$cap=array('field_key'=>150,'label'=>200,'shortcode'=>150,'fallback_text'=>500)[$field]??null;if($v!==null&&$cap!==null&&Compat::length($v)>$cap){throw new ValidationFailure('String should have at most '.$cap.' characters',$field);}if($v!==null&&in_array($field,array('field_key','shortcode'),true)){$v=Templating::key($v);if($v===''){throw new ValidationFailure('Value error, Short code must contain at least one letter or number',$field);}if(strlen($v)>150){throw new ValidationFailure('Value error, Short code is too long',$field);}}$out[$field]=$v;}return $out;}
    private function out(array $row){$row['created_at']=Records::iso($row['created_at']);$row['updated_at']=Records::iso($row['updated_at']);return $row;}
    public function create($body){$d=self::input($body);if($this->db->one('contact_variables',array('field_key'=>$d['field_key']))){throw new AuthFailure(409,'A variable with this field key already exists');}$short=$d['shortcode']??$d['field_key'];$clash=$this->db->one('contact_variables',array('shortcode'=>$short));if($clash){throw new AuthFailure(409,"The short code '".$short."' is already used by ".$clash['label']);}$d['shortcode']=$short;$d['label']=$d['label']!==null&&$d['label']!==''?$d['label']:self::humanize($d['field_key']);$d['source']='imported';return $this->out($this->records->create('contact_variables',$d));}
    public function update($id,$body){$d=self::input($body,true);$r=$this->db->one('contact_variables',array('id'=>$id));if(!$r){throw new AuthFailure(404,'Variable not found');}if(isset($d['shortcode'])&&$d['shortcode']!==''){$clashes=$this->db->rows('SELECT label FROM '.$this->table('contact_variables').' WHERE shortcode=%s AND id<>%d LIMIT 1',array($d['shortcode'],$id));if($clashes){throw new AuthFailure(409,"The short code '".$d['shortcode']."' is already used by '".$clashes[0]['label']."'. Two variables cannot answer to the same short code.");}}foreach($d as $k=>$v){if($v===$r[$k]){unset($d[$k]);}}if($d){$d['updated_at']=$this->records->now();$this->db->update('contact_variables',$d,array('id'=>$id));}return $this->out($this->db->one('contact_variables',array('id'=>$id)));}
    public function delete($id){$r=$this->db->one('contact_variables',array('id'=>$id));if(!$r){throw new AuthFailure(404,'Variable not found');}if($r['source']==='standard'){throw new AuthFailure(400,'Built-in variables cannot be deleted. Deactivate it instead.');}$this->db->delete('contact_variables',array('id'=>$id));}
    public function sync($limit=null){$rows=$this->rows();$existing=array_fill_keys(array_column($rows,'field_key'),true);foreach(self::standards() as $s){if(!isset($existing[$s[0]])){$this->records->create('contact_variables',array('field_key'=>$s[0],'label'=>$s[1],'shortcode'=>$s[0],'description'=>$s[2],'source'=>'standard'));}}$rows=$this->rows();$byKey=array();$taken=array();foreach($rows as $r){$byKey[$r['field_key']]=$r;$taken[$r['shortcode']]=true;}$counts=array();$samples=array();$contacts=$limit?array_map(function($r){return $this->db->decode('contacts',$r);},$this->db->rows('SELECT * FROM '.$this->table('contacts').' ORDER BY id ASC LIMIT %d',array($limit))):$this->db->select('contacts',array(),2147483647);foreach($contacts as $c){foreach(self::standards() as $s){$key=$s[0];$value=$c[$key]??null;if($key==='full_name'){$parts=array();foreach(array('first_name','last_name') as $f){if(($c[$f]??null)!==null&&$c[$f]!==''){$parts[]=$c[$f];}}$value=implode(' ',$parts);}$text=Templating::clean($value);if($text!==''){$counts[$key]=($counts[$key]??0)+1;if(!isset($samples[$key])){$samples[$key]=$text;}}}foreach(Templating::custom($c,true) as $key=>$text){if($text!==''){$counts[$key]=($counts[$key]??0)+1;if(!isset($samples[$key])){$samples[$key]=$text;}}elseif(!isset($counts[$key])){$counts[$key]=0;}}}$discovered=0;foreach($counts as $key=>$count){$key=(string)$key;if(!isset($byKey[$key])){$short=$key;$suffix=2;while(isset($taken[$short])){$short=$key.'_'.($suffix++);}$taken[$short]=true;$byKey[$key]=$this->records->create('contact_variables',array('field_key'=>$key,'label'=>self::humanize($key),'shortcode'=>$short,'source'=>'imported'));$discovered++;}$r=$byKey[$key];$changes=array();if($r['contact_count']!==$count){$changes['contact_count']=$count;}if(isset($samples[$key])&&$samples[$key]!==''){$sample=implode('',array_map(array(Compat::class,'chr'),array_slice(Compat::points($samples[$key]),0,500)));if($sample!==$r['sample_value']){$changes['sample_value']=$sample;}}if($changes){$changes['updated_at']=$this->records->now();$this->db->update('contact_variables',$changes,array('id'=>$r['id']));}}return array('discovered'=>$discovered,'total'=>count($byKey),'contacts_scanned'=>count($contacts));}
    public function listing($search=null,$source=null,$sync=true){$stats=$sync?$this->sync():null;$rows=$this->rows();$term=$search!==null&&$search!==''?Compat::lower(Compat::strip($search)):null;$rows=array_values(array_filter($rows,function($r)use($source,$term){if($source!==null&&$source!==''&&$r['source']!==$source){return false;}if($term===null){return true;}foreach(array('label','shortcode','field_key') as $f){if(strpos(Compat::lower($r[$f]),$term)!==false){return true;}}return false;}));usort($rows,function($a,$b){$x=$a['source']!=='standard';$y=$b['source']!=='standard';return $x!==$y?($x?1:-1):strcmp(Compat::lower($a['label']),Compat::lower($b['label']));});return array('total'=>count($rows),'items'=>array_map(array($this,'out'),$rows),'sync'=>$stats);}
    public function maps(){$aliases=array();$fallbacks=array();foreach($this->rows() as $r){if(!$r['is_active']){continue;}$key=Templating::key($r['field_key']);$aliases[Templating::key($r['shortcode'])]=$key;if(!isset($aliases[$key])){$aliases[$key]=$key;}$label=Templating::key($r['label']);if(!isset($aliases[$label])){$aliases[$label]=$key;}if($r['fallback_text']!==null&&$r['fallback_text']!==''){$fallbacks[$key]=$r['fallback_text'];}}return array($aliases,$fallbacks);}
    public function analyze($body,$contact=null){list($aliases,$fallbacks)=$this->maps();$context=Templating::context($contact);$resolved=array();$empty=array();$unknown=array();foreach(Templating::placeholders($body) as $key){if(!array_key_exists($key,$aliases)){$unknown[]=$key;continue;}$field=$aliases[$key];$value=$context[$field]??'';if($value!==''){$resolved[]=array('shortcode'=>$key,'field_key'=>$field,'value'=>$value);}elseif(($fallbacks[$field]??'')!==''){$resolved[]=array('shortcode'=>$key,'field_key'=>$field,'value'=>$fallbacks[$field]);}else{$empty[]=array('shortcode'=>$key,'field_key'=>$field);}}return array('preview'=>Templating::render($body,$contact,$aliases,$fallbacks),'resolved'=>$resolved,'empty'=>$empty,'unknown'=>$unknown,'will_remove'=>array_merge(array_column($empty,'shortcode'),$unknown));}
    public function knownKeys(){list($aliases)=$this->maps();$keys=Templating::builtin();foreach(self::standards() as $s){$keys[]=Templating::key($s[0]);}$keys=array_merge($keys,array_keys($aliases),array_values($aliases));return array_values(array_unique(array_map('strval',$keys)));}
    private static function scanUnknown(array $texts,array $known){$out=array();$seen=array();foreach($texts as $text){foreach(Templating::unknown($text,$known) as $name){$key=Templating::key($name);if(!isset($seen[$key])){$out[]=$name;$seen[$key]=true;}}}return $out;}
    public function unknownIn(array $texts,array $extra=array()){$known=array_values(array_unique(array_merge($this->knownKeys(),$extra)));$unknown=self::scanUnknown($texts,$known);if($unknown){$this->sync();$known=array_values(array_unique(array_merge($this->knownKeys(),$extra)));$unknown=self::scanUnknown($texts,$known);}return array($unknown,$known);}
    public static function unknownError(array $unknown,array $known){$suggestions=new \stdClass();$parts=array();foreach($unknown as $name){$hit=Suggestions::closest($name,$known);if($hit!==null){$suggestions->$name=$hit;}$parts[]='{{'.$name.'}}'.($hit!==null?' (did you mean {{'.$hit.'}}?)':'');}return array('code'=>'UNKNOWN_TEMPLATE_VARIABLES','message'=>'This message uses '.(count($parts)===1?'a variable that does not exist: ':'variables that do not exist: ').implode(', ',$parts).'. Fix the spelling, or add the variable on the Variables page.','unknown'=>$unknown,'suggestions'=>$suggestions);}
    public function preview($body,$subject=null,$html=null,$contact=null,array $overrides=array()){
        list($aliases,$fallbacks)=$this->maps();$values=$contact===null?array('first_name'=>'John','last_name'=>'Doe','business_name'=>'Acme Ltd','phone_number'=>'08012345678','email'=>'john.doe@example.com','city'=>'Lagos','state'=>'Lagos','website'=>'https://example.com','industry'=>'Technology'):array();foreach($overrides as $k=>$v){if($v!==null){$values[$k]=$v;}}$extra=array_map(array(Templating::class,'key'),array_keys($values));$extra=array_merge($extra,array_map('strval',array_keys(Templating::context($contact))));list($unknown,$known)=$this->unknownIn(array($body,$subject,$html),$extra);$render=function($text)use($contact,$aliases,$fallbacks,$known,$values){return $text===null||$text===''?null:Templating::render($text,$contact,$aliases,$fallbacks,'mark',$known,$values);};$warnings=array();foreach($unknown as $name){$hint=Suggestions::closest($name,$known);$warnings[]='{{'.$name.'}} is not a known variable'.($hint!==null?' — did you mean {{'.$hint.'}}?':'').' A real send would remove it, and saving a template with it is refused.';}$info=null;if($contact!==null){$c=(array)$contact;$parts=array();foreach(array('first_name','last_name') as $k){if(($c[$k]??null)!==null&&$c[$k]!==''){$parts[]=$c[$k];}}$name=implode(' ',$parts);$info=array('id'=>$c['id'],'name'=>$name!==''?$name:($c['business_name']??''));}return array('body'=>$render($body)??'','subject'=>$render($subject),'html'=>$render($html),'unknown_variables'=>$unknown,'warnings'=>$warnings,'contact'=>$info,'sample'=>$contact===null);
    }

}
